import * as T from 'three';
import {box,cylinder,sign,mat,tree} from './models.js';
const distSegment=(x,z,r)=>{const dx=r.b[0]-r.a[0],dz=r.b[1]-r.a[1],t=Math.max(0,Math.min(1,((x-r.a[0])*dx+(z-r.a[1])*dz)/(dx*dx+dz*dz)));return Math.hypot(x-r.a[0]-dx*t,z-r.a[1]-dz*t);};
function roof(root,b){const h=b.levels*3,shape=new T.Shape();shape.moveTo(-b.w/2-.4,0);shape.lineTo(0,2.5+b.w*.035);shape.lineTo(b.w/2+.4,0);shape.closePath();const m=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:b.d+.8,bevelEnabled:false}),mat(b.x<0?'#887762':'#697982'));m.position.set(b.x,h+.05,b.z-b.d/2-.4);m.castShadow=true;root.add(m);box(root,1.1,2.2,.9,'#ad937d',b.x+b.w*.2,h+2,b.z);}
function bench(root,x,z,yaw=0){const g=new T.Group();g.position.set(x,0,z);g.rotation.y=yaw;root.add(g);box(g,2.6,.16,.65,'#8b7255',0,.65,0);box(g,2.6,.65,.12,'#8b7255',0,1,-.25);for(const x of[-.9,.9])box(g,.12,.6,.5,'#465952',x,.3,0);}
export function enrichCity(root,block,roads){
for(const [i,b]of block.buildings.entries()){
 const h=b.levels*3;
 if(['town','civic'].includes(b.style)){roof(root,b);for(const y of[.65,h-.3])box(root,b.w+.3,.24,b.d+.3,'#ded8c4',b.x,y,b.z);for(let level=1;level<b.levels;level++)box(root,b.w+.18,.11,b.d+.18,'#c6bfae',b.x,level*3+.2,b.z);for(let x=b.x-b.w/2+2;x<b.x+b.w/2-1;x+=3.5){for(let y=2;y<h-.4;y+=3){for(const side of[-1,1])box(root,.35,1.5,.15,i%2?'#688377':'#7c7064',x+side*.85,y,b.z+b.d/2+.13);box(root,1.8,.12,.45,'#e0d8c5',x,y-.77,b.z+b.d/2+.2);}}box(root,1.5,2.4,.2,'#455e5e',b.x,1.5,b.z+b.d/2+.15);box(root,1.8,.16,1,'#bdb9a3',b.x,.38,b.z+b.d/2+.4);if(b.style==='town'&&i%3===0){const color=['#55766c','#a3654d','#617b8a'][i%3];box(root,b.w-.7,.3,2.1,color,b.x,3.1,b.z+b.d/2+.65);sign(root,['ÉPICERIE','LIBRAIRIE','ARTISAN','BRASSERIE'][i%4],b.w-1,.65,b.x,3.7,b.z+b.d/2+.25,color);}}
 if(b.style==='tower'){box(root,b.w+.8,.35,b.d+.8,'#d3d5c9',b.x,h+.2,b.z);box(root,7,1.4,4,'#83938f',b.x,h+.9,b.z);for(let y=5;y<h;y+=3)for(const x of[b.x-b.w*.26,b.x+b.w*.26]){box(root,6,.18,2.2,'#b5c4c0',x,y,b.z+b.d/2+.9);box(root,6,.8,.12,'#758f94',x,y+.45,b.z+b.d/2+1.9);for(const xx of[-2.9,2.9])box(root,.12,.8,2,'#91a5a5',x+xx,y+.45,b.z+b.d/2+.9);}box(root,3,2.6,.3,'#3e6067',b.x,1.5,b.z+b.d/2+.2);for(let k=0;k<3;k++)tree(root,b.x-b.w*.4+k*b.w*.4,b.z-b.d/2-5,.6+k*.12,k);}
}
// Mairie, placette minérale et clocher : repères visibles à l’échelle du quartier.
sign(root,'MAIRIE DE VALMONT',23,1,-53,5,-51.3,'#cfc6ac','#3f5354');box(root,8,6,8,'#c9bca2',-53,12,-63);const spire=new T.Mesh(new T.ConeGeometry(6,7,4),mat('#62737d'));spire.rotation.y=Math.PI/4;spire.position.set(-53,18,-63);root.add(spire);const dial=cylinder(root,1.2,1.2,.12,'#f1e6c5',-53,13,-58.9,24);dial.rotation.x=Math.PI/2;box(root,.07,.9,.08,'#3d5155',-53,13.3,-58.8);box(root,.7,.07,.08,'#3d5155',-52.7,13,-58.8);
for(const [x,z]of[[-34,-44],[-69,-44],[154,50],[260,50],[30,181],[94,189]]){bench(root,x,z);cylinder(root,.35,.35,.9,'#506b65',x+2,.6,z,8);}
// Mobilier urbain : arrêts de bus, traversées, stationnement, jardinières.
for(const [x,z]of[[6,48],[146,-47],[286,47]]){box(root,7,.16,2.8,'#596f71',x+2,2.8,z);for(const dx of[-1,5])box(root,.1,2.5,.1,'#718b89',x+dx,1.4,z);box(root,6,2,.08,'#86aaad',x+2,1.6,z-1.1);bench(root,x+2,z);sign(root,'BUS',1.2,.8,x-2,2.5,z,'#34778b');}
for(const r of roads.filter(r=>!r.trail&&!r.express&&!r.name.includes('(simulation)'))){const len=Math.hypot(r.b[0]-r.a[0],r.b[1]-r.a[1]);if(len<25)continue;const dx=(r.b[0]-r.a[0])/len,dz=(r.b[1]-r.a[1])/len;for(let j=-3;j<=3;j++){const stripe=box(root,.65,.025,2.7,'#e1e4d5',r.a[0]+dx*9+dz*j*1.2,.28,r.a[1]+dz*9-dx*j*1.2);stripe.rotation.y=Math.atan2(dx,dz);}for(let d=22;d<len-15;d+=27){const x=r.a[0]+dx*d+dz*7.5,z=r.a[1]+dz*d-dx*7.5;if(x>5&&x<16&&z>111&&z<140)continue;if(block.buildings.some(b=>Math.abs(x-b.x)<b.w/2+1&&Math.abs(z-b.z)<b.d/2+1))continue;box(root,2,.5,2,'#b9b5a0',x,.4,z);tree(root,x,z,.65,1);}}
// Parc de quartier : chemin courbe, jeux et jardins familiaux.
const walk=new T.CatmullRomCurve3([new T.Vector3(35,.3,185),new T.Vector3(55,.3,202),new T.Vector3(85,.3,211),new T.Vector3(123,.3,207),new T.Vector3(158,.3,198)]);const walkMesh=new T.Mesh(new T.TubeGeometry(walk,40,1.2,5,false),mat('#c7b992'));walkMesh.scale.y=.1;walkMesh.position.y=.01;root.add(walkMesh);for(let i=0;i<12;i++)tree(root,30+i*12,250+(i%3)*5,.9,i%4);for(let i=0;i<5;i++){box(root,6,.3,9,'#8b7753',190+i*9,.25,225);for(let j=0;j<4;j++)box(root,.5,.3,7,'#79944e',188+i*9+j*1.2,.6,225);}for(const x of[176,182]){box(root,.16,3,.16,'#a4784b',x,1.6,216);box(root,.12,2.3,.12,'#596d6c',x+.8,1.5,216);}box(root,8,.18,.2,'#a4784b',180,3.1,216);
// Forêt dense : plusieurs essences et tailles, sous-bois, clairières et pistes dégagées.
let seed=731;const rnd=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);const trails=roads.filter(r=>r.trail);let planted=0;
for(let i=0;i<1900;i++){const x=-265+rnd()*252,z=-231+rnd()*158;if(roads.some(r=>distSegment(x,z,r)<(r.trail?7.2:11)))continue;if((x+111)**2+(z+95)**2<100)continue;const scale=.8+rnd()*1.4;tree(root,x,z,scale,i%4);planted++;if(i%5===0){const shrub=new T.Mesh(new T.IcosahedronGeometry(.9+rnd(),0),mat('#526a40'));shrub.position.set(x+2,.6,z+1);shrub.scale.y=.65;root.add(shrub);}if(i%29===0){const rock=new T.Mesh(new T.DodecahedronGeometry(1.1,0),mat('#8d927d'));rock.position.set(x-2,.4,z);rock.scale.set(1,.7,1.5);root.add(rock);}}
for(const r of trails){const dx=r.b[0]-r.a[0],dz=r.b[1]-r.a[1],len=Math.hypot(dx,dz);for(const side of[-1,1]){const rut=box(root,.45,.025,len,'#938568',(r.a[0]+r.b[0])/2+dz/len*side*1.1,.125,(r.a[1]+r.b[1])/2-dx/len*side*1.1);rut.rotation.y=Math.atan2(dx,dz);}}
for(const [x,z]of[[-31,-103],[-155,-164],[-83,-175]]){cylinder(root,.13,.16,2.3,'#806846',x,1.2,z,6);sign(root,'PISTE DFCI',4,.7,x,2,z,'#667248','#f1ebce');}
root.userData.forestTrees=planted;
}
